import * as T from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
import {mergeGeometries} from './vendor/utils/BufferGeometryUtils.js';
import {createGardenArt} from './garden-art.js';
import {RanchRenderer} from './ranch-renderer.js';
import {ranchMaterial} from './tile-materials.js';
import {calibratedScale,modelDimensions,calibrationStatus} from './model-calibration.js';
import {composeGarden,gardenTerrain,clipHex,inHex,GARDEN_ASSETS,DEFAULT_GARDEN} from './garden-farm.js';
const $=id=>document.getElementById(id),host=$('scene-viewport'),scene=new T.Scene();scene.background=new T.Color('#e4e9d8');
const renderer=new RanchRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.shadowMap.autoUpdate=false;host.append(renderer.domElement);
const camera=new T.PerspectiveCamera(37,1,.1,1000),orbit=new OrbitControls(camera,renderer.domElement);orbit.mouseButtons={LEFT:null,MIDDLE:T.MOUSE.ROTATE,RIGHT:T.MOUSE.PAN};orbit.enableDamping=false;orbit.maxPolarAngle=Math.PI*.46;orbit.minDistance=15;orbit.maxDistance=450;
scene.add(new T.HemisphereLight('#fff6df','#728779',1.15));const sun=new T.DirectionalLight('#fff0d2',2);sun.position.set(-60,100,40);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-65,right:65,top:65,bottom:-65,near:1,far:250});sun.shadow.normalBias=.06;scene.add(sun);
const labels=document.createElement('div');labels.className='garden-labels';host.append(labels);let world=null,terrain=null,result=null,busy=false,labelEntries=[],groundSurface=null,request=0;
const art=await createGardenArt(),{dimensions,refreshDimensions,addAsset,load}=art;
function box(g,x,y,z,w,h,d,color,role='timber'){const m=new T.Mesh(new T.BoxGeometry(w,h,d),ranchMaterial(color,role));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;g.add(m);return m;}
function mesh(geo,color,role='ground'){const m=new T.Mesh(geo,ranchMaterial(color,role));m.receiveShadow=true;return m;}
function release(group){if(!group)return;group.traverse(o=>{if(!o.userData.template)o.geometry?.dispose();if(!o.userData.template&&o.material&&!o.material.userData.shared)o.material.dispose();});}
function render(){renderer.render(scene,camera);for(const l of labelEntries){const p=l.point.clone().project(camera);l.element.hidden=!$('garden-labels').checked||l.id!==$('garden-inspect').value||p.z<0||p.z>1||Math.abs(p.x)>1||Math.abs(p.y)>1;l.element.style.left=(p.x+1)*host.clientWidth/2+'px';l.element.style.top=(1-p.y)*host.clientHeight/2+'px';}}
orbit.addEventListener('change',()=>{render();window.RanchView?.changed();});
function fit(top=false,whole=false){
 const w=host.clientWidth,h=host.clientHeight,drawer=document.getElementById('app-controls'),dw=w>=800&&drawer?.open&&drawer.getBoundingClientRect().left<w?Math.min(330,drawer.getBoundingClientRect().width):0,box=new T.Box3();
 if(result&&!whole)for(const o of result.items){box.expandByPoint(new T.Vector3(o.x-o.w/2,o.y,o.z-o.d/2));box.expandByPoint(new T.Vector3(o.x+o.w/2,o.y+o.h,o.z+o.d/2));}
 const center=box.isEmpty()?new T.Vector3():box.getCenter(new T.Vector3()),size=box.isEmpty()?new T.Vector3(100,5,100):box.getSize(new T.Vector3()),extent=whole?54:Math.max(size.x,size.z)*(w<800?.54:.42)+2,half=Math.min(camera.fov*Math.PI/360,Math.atan(Math.tan(camera.fov*Math.PI/360)*Math.max(.5,(w-dw)/h))),distance=extent/Math.sin(half);
 camera.setViewOffset(w,h,dw/2,0,w,h);orbit.target.copy(center);camera.position.copy(new T.Vector3(top?.001:.75,top?1:1.12,top?.001:1.1).normalize().multiplyScalar(distance).add(center));orbit.update();render();window.RanchView?.changed();
}
window.addEventListener('resize',()=>fit());
new ResizeObserver(()=>{renderer.setSize(host.clientWidth,host.clientHeight,false);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();fit();}).observe(host);
function terrainMesh(t,carved,texture){const positions=[],water=[],colors=[],uvs=[],groundColors=['#aebc88','#b9c591','#9daf7e'];
 for(let x=-60;x<60;x+=2.5)for(let z=-60;z<60;z+=2.5){let poly=[{x,z},{x:x+2.5,z},{x:x+2.5,z:z+2.5},{x,z:z+2.5}];if(carved)poly=clipHex(poly);if(poly.length<3)continue;const s=t.sample(x+1.25,z+1.25),color=new T.Color(s.bank<2?'#c8c2a2':'#ffffff');for(let i=1;i<poly.length-1;i++)for(const p of [poly[0],poly[i+1],poly[i]]){positions.push(p.x,t.height(p.x,p.z),p.z);uvs.push((p.x+60)/120,1-(p.z+60)/120);colors.push(color.r,color.g,color.b);}
  if(s.bank<0){const brook=t.world.water.brook.centerline,idx=Math.max(0,Math.min(brook.length-1,Math.round((x+90)/180*(brook.length-1)))),h=brook[idx][2]-t.datum;for(let i=1;i<poly.length-1;i++)for(const p of [poly[0],poly[i],poly[i+1]])water.push(p.x,h+.03,p.z);}
 }
 const g=new T.Group(),geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.setAttribute('color',new T.Float32BufferAttribute(colors,3));geo.setAttribute('uv',new T.Float32BufferAttribute(uvs,2));geo.computeVertexNormals();const ground=new T.Mesh(geo,new T.MeshLambertMaterial({vertexColors:true,map:texture}));ground.receiveShadow=true;g.add(ground);
 if(water.length){const waterGeo=new T.BufferGeometry();waterGeo.setAttribute('position',new T.Float32BufferAttribute(water,3));waterGeo.computeVertexNormals();const m=mesh(waterGeo,'#87b5af');m.material.side=T.DoubleSide;g.add(m);}
 // The cut exposes a continuous earth edge without clipping buildings or routes.
 const boundary=carved?Array.from({length:6},(_,i)=>({x:50*Math.sin(i*Math.PI/3),z:50*Math.cos(i*Math.PI/3)})):[{x:-60,z:-60},{x:-60,z:60},{x:60,z:60},{x:60,z:-60}],side=[];
 for(let i=0;i<boundary.length;i++){const a=boundary[i],b=boundary[(i+1)%boundary.length],n=40;for(let j=0;j<n;j++){const p={x:a.x+(b.x-a.x)*j/n,z:a.z+(b.z-a.z)*j/n},q={x:a.x+(b.x-a.x)*(j+1)/n,z:a.z+(b.z-a.z)*(j+1)/n};for(const v of [[p.x,t.height(p.x,p.z),p.z],[q.x,t.height(q.x,q.z),q.z],[p.x,-5,p.z],[q.x,t.height(q.x,q.z),q.z],[q.x,-5,q.z],[p.x,-5,p.z]])side.push(...v);}}
 const sideGeo=new T.BufferGeometry();sideGeo.setAttribute('position',new T.Float32BufferAttribute(side,3));sideGeo.computeVertexNormals();const wall=mesh(sideGeo,'#958467');wall.material.side=T.DoubleSide;g.add(wall);return g;
}
function paintGround(surface,activityId='all'){
 const {canvas,texture,plan}=surface,c=canvas.getContext('2d'),scale=canvas.width/120,at=v=>(v+60)*scale;c.fillStyle='#afbc8d';c.fillRect(0,0,canvas.width,canvas.height);
 for(const area of plan.areas||[]){c.save();c.shadowColor='#b2ad86';c.shadowBlur=8;c.fillStyle='#b9b28d';c.beginPath();c.roundRect(at(area.x-area.w/2),at(area.z-area.d/2),area.w*scale,area.d*scale,2*scale);c.fill();c.restore();}
 const process=plan.semantics.processes.find(p=>p.id===activityId),targets=process?[process.from,process.to]:[];
 for(const r of plan.routes){const active=process&&(targets.includes(r.to)||targets.includes(r.from)||targets.includes('beds')&&(r.to==='beds'||r.to.startsWith('bed-')));if(r.surface==='threshold'&&!active)continue;
 c.save();c.strokeStyle=active?'#c99862':r.surface==='worn'?'#c4b58d':r.surface==='soil'?'#a5ad81':'#b4b68b';c.lineWidth=r.width*scale;c.lineCap=c.lineJoin='round';c.shadowColor=c.strokeStyle;c.shadowBlur=3;c.beginPath();r.points.forEach((p,i)=>i?c.lineTo(at(p.x),at(p.z)):c.moveTo(at(p.x),at(p.z)));c.stroke();c.restore();}texture.needsUpdate=true;
}
async function draw(next){const t=gardenTerrain(next.recipe),group=new T.Group(),canvas=document.createElement('canvas');canvas.width=canvas.height=1024;const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;texture.anisotropy=4;const surface={canvas,texture,plan:next};paintGround(surface);group.add(terrainMesh(t,$('garden-carved').checked,texture));
 await art.drawItems(group,next.items);
 await art.drawContext(group,next,t.height);
 const treeDims=dimensions['tree-standing'],treeRadius=Math.hypot(treeDims.w,treeDims.d)/2;for(const tree of t.world.vegetation){const x=tree.position[0]-90,z=90-tree.position[1];if(Math.abs(x)>58||Math.abs(z)>58||$('garden-carved').checked&&!inHex(x,z,treeRadius+1)||next.items.some(o=>Math.hypot(x-o.x,z-o.z)<Math.hypot(o.w,o.d)/2+treeRadius+2)||next.routes.some(r=>r.points.some(p=>Math.hypot(x-p.x,z-p.z)<r.width/2+treeRadius+1)))continue;const a=await addAsset(group,'tree-standing',x,t.height(x,z),z);a.userData.purpose='decoration';}
 if(world){scene.remove(world);release(world);groundSurface?.texture.dispose();}world=group;terrain=t;groundSurface=surface;scene.add(world);renderer.shadowMap.needsUpdate=true;
 labels.replaceChildren();labelEntries=[];for(const o of next.items){const el=document.createElement('span');el.className='garden-label';el.textContent=o.id.replaceAll('-',' ');labels.append(el);labelEntries.push({id:o.id,element:el,point:new T.Vector3(o.x,o.y+o.h+1,o.z)});}
 result=next;updateInfo();render();window.RanchView?.changed();
}
function updateInfo(){if(!result)return;$('garden-sentence').textContent=result.grammar.sentence;$('garden-caption').textContent=`${result.recipe.beds} individual beds · shared workcourt and tending aisles`;$('garden-validation').textContent=result.validation.checks.join(' · ');$('garden-inspect').replaceChildren(...result.items.map(o=>new Option(o.id.replaceAll('-',' '),o.id)));$('garden-calibration').textContent=calibrationStatus.state==='synced'?'Using shared model sizes.':'Using cached or project model sizes; shared calibration is unavailable.';inspect();activity();}
function inspect(){if(!result)return;const o=result.items.find(o=>o.id===$('garden-inspect').value);if(!o)return;$('garden-purpose').textContent=`${o.purpose}. ${o.reason}. ${o.w.toFixed(1)} × ${o.d.toFixed(1)} m. Activities: ${o.activities.join(', ')}. Behavior planned.`;labelEntries.forEach(l=>l.element.classList.toggle('active',l.id===o.id));render();window.RanchView?.changed();}
function activity(){if(!result||!groundSurface)return;const id=$('garden-process').value,p=result.semantics.processes.find(p=>p.id===id);paintGround(groundSurface,id);$('garden-activity').textContent=p?`${p.input} → ${p.output}. Planned activity; quantities undecided.`:'Shared workcourt, a collection approach and narrow tending aisles.';render();window.RanchView?.changed();}
function read(){return {seed:Number($('garden-seed').value),layout:$('garden-layout').value,terrain:$('garden-terrain').value,beds:Number($('garden-beds').value),carved:$('garden-carved').checked};}
function setControls(p){$('garden-seed').value=p.seed;$('garden-layout').value=p.layout;document.querySelectorAll('[data-garden-layout]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.gardenLayout===p.layout)));$('garden-terrain').value=p.terrain;$('garden-beds').value=p.beds;$('garden-carved').checked=p.carved;}
async function build(recipe=read()){if(busy)return;busy=true;const ticket=++request;for(const id of ['garden-build','garden-vary','garden-load','garden-save','garden-export','garden-carved'])$(id).disabled=true;$('garden-status').textContent='Reading terrain, arranging work and checking access…';window.RanchView?.changed();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));try{await refreshDimensions();const next=composeGarden(recipe,dimensions);if(ticket!==request)return;await draw(next);setControls(next.recipe);fit();$('garden-status').textContent='Garden composed. Every working place has access.';}catch(e){$('garden-status').textContent=e.message;if(result)$('garden-status').textContent+=' Previous garden retained.';}finally{busy=false;for(const id of ['garden-build','garden-vary','garden-load','garden-save','garden-export','garden-carved'])$(id).disabled=false;window.RanchView?.changed();}}
document.querySelectorAll('[data-garden-layout]').forEach(b=>b.onclick=()=>{$('garden-layout').value=b.dataset.gardenLayout;build();});$('garden-build').onclick=()=>build();$('garden-vary').onclick=()=>{const p=read();p.seed=crypto.getRandomValues(new Uint32Array(1))[0]||1;build(p)};$('garden-fit').onclick=()=>fit(false,true);$('garden-top').onclick=()=>fit(true);$('garden-process').onchange=activity;$('garden-inspect').onchange=()=>{$('garden-labels').checked=true;inspect();};$('garden-labels').onchange=()=>{render();window.RanchView?.changed()};$('garden-carved').onchange=async()=>{if(result){await draw({...result,recipe:{...result.recipe,carved:$('garden-carved').checked}});fit();}};
$('garden-save').onclick=()=>{if(!result)return;try{localStorage.setItem('ranch-garden-recipe-v1',JSON.stringify(result.recipe));$('garden-status').textContent='Garden recipe saved.';}catch(e){$('garden-status').textContent=e.message;}};
$('garden-load').onclick=()=>{try{const p=JSON.parse(localStorage.getItem('ranch-garden-recipe-v1'));if(!p)throw Error('No saved garden on this browser.');build(p)}catch(e){$('garden-status').textContent=e.message}};
$('garden-export').onclick=()=>{if(!result)return;const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='garden-farm-'+result.recipe.seed+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
window.RanchView?.register('gardenFarm',()=>({busy,recipe:result?.recipe,draft:read(),sentence:result?.grammar.sentence,validation:result?.validation,terrain:result?{prefabId:result.terrain.prefabId,schemaVersion:result.terrain.schemaVersion,verticalDisplayOffset:result.verticalDisplayOffset}:null,items:result?.items.map(o=>({id:o.id,model:o.model,purpose:o.purpose,x:o.x,y:o.y,z:o.z,w:o.w,d:o.d})),routes:result?.routes.map(r=>({id:r.id,traffic:r.traffic,surface:r.surface,width:r.width,from:r.from,to:r.to})),activity:$('garden-process').value,selected:$('garden-inspect').value,carved:$('garden-carved').checked,calibration:calibrationStatus,camera:camera.position.toArray(),target:orbit.target.toArray()}),render);
window.addEventListener('ranch-model-calibration',()=>{if(result&&!busy)build(result.recipe)});
setControls(DEFAULT_GARDEN);await build(DEFAULT_GARDEN);fit();if(innerWidth<800)window.RanchDrawers?.close();
